add("vsa1", ("संसाधनों के अंधाधुंध उपयोग से पैदा हुई कोई दो समस्याएँ बताइए।", "સંસાધનોના આડેધડ ઉપયોગથી ઊભી થયેલી કોઈ બે સમસ્યાઓ જણાવો."),
    {0: ("कुछ व्यक्तियों के लालच के लिए संसाधनों का ह्रास।", "થોડી વ્યક્તિઓના લોભ માટે સંસાધનોનો ઘટાડો."), 1: ("कुछ हाथों में संसाधनों का संचय, जिससे समाज संपन्न और संसाधनहीन में बँटा; और भूमंडलीय तापन और प्रदूषण जैसे वैश्विक पारिस्थितिकी संकट।", "થોડા હાથોમાં સંસાધનોનો સંગ્રહ, જેથી સમાજ ધનિક અને વંચિતોમાં વહેંચાયો; અને વૈશ્વિક તાપમાન વધારો અને પ્રદૂષણ જેવી વૈશ્વિક પર્યાવરણીય કટોકટી.")})
add("vsa2", ("रियो डी जेनेरो पृथ्वी सम्मेलन (1992) के दो मुख्य निर्णय क्या थे?", "રિયો ડી જાનેરો પૃથ્વી પરિષદ (1992)ના બે મુખ્ય નિર્ણયો કયા હતા?"),
    {0: ("नेताओं ने भूमंडलीय जलवायु परिवर्तन और जैविक विविधता पर घोषणा-पत्र पर हस्ताक्षर किए और भूमंडलीय वन सिद्धांतों का समर्थन किया।", "નેતાઓએ વૈશ્વિક આબોહવા પરિવર્તન અને જૈવવિવિધતા અંગેના જાહેરનામા પર સહી કરી અને વૈશ્વિક વન સિદ્ધાંતોને ટેકો આપ્યો."), 1: ("उन्होंने सतत पोषणीय विकास के लिए एजेंडा 21 स्वीकार किया, जिसमें हर स्थानीय निकाय से अपना स्थानीय एजेंडा 21 बनाने को कहा गया।", "તેમણે ટકાઉ વિકાસ માટે એજન્ડા 21 સ્વીકાર્યો, જેમાં દરેક સ્થાનિક સરકારને પોતાનો સ્થાનિક એજન્ડા 21 બનાવવા કહેવાયું.")})
add("vsa3", ("भारत के केवल लगभग 93 प्रतिशत क्षेत्र के ही भू-उपयोग आँकड़े क्यों उपलब्ध हैं?", "ભારતના ફક્ત આશરે 93 ટકા વિસ્તારના જ ભૂમિ ઉપયોગના આંકડા કેમ ઉપલબ્ધ છે?"),
    {0: ("असम को छोड़कर अधिकांश पूर्वोत्तर राज्यों में भू-उपयोग की सूचना पूरी तरह नहीं दी गई है।", "આસામ સિવાયનાં મોટા ભાગનાં ઈશાન રાજ્યોમાં ભૂમિ ઉપયોગની માહિતી પૂરી અપાઈ નથી."), 1: ("जम्मू-कश्मीर के पाकिस्तान और चीन अधिकृत कुछ क्षेत्रों का सर्वेक्षण नहीं हुआ है।", "જમ્મુ-કાશ્મીરના પાકિસ્તાન અને ચીનના કબજાવાળા કેટલાક વિસ્તારોનું સર્વેક્ષણ થયું નથી.")})
add("sa1", ("भारत में संसाधन नियोजन के तीन सोपान समझाइए।", "ભારતમાં સંસાધન આયોજનનાં ત્રણ સોપાનો સમજાવો."),
    {0: ("देश के प्रदेशों में संसाधनों की पहचान और तालिका बनाना: सर्वेक्षण, मानचित्र बनाना और गुणात्मक और मात्रात्मक अनुमान।", "દેશના પ્રદેશોમાં સંસાધનોની ઓળખ અને યાદી બનાવવી: સર્વેક્ષણ, નકશા બનાવવા અને ગુણાત્મક અને જથ્થાત્મક અંદાજ."),
     1: ("योजनाओं को लागू करने के लिए उपयुक्त प्रौद्योगिकी, कौशल और संस्थागत ढाँचे वाला नियोजन ढाँचा तैयार करना।", "યોજનાઓના અમલ માટે યોગ્ય ટેકનોલોજી, કૌશલ્ય અને સંસ્થાકીય માળખાવાળું આયોજન માળખું તૈયાર કરવું."),
     2: ("संसाधन विकास योजनाओं का समग्र राष्ट्रीय विकास योजनाओं से समन्वय।", "સંસાધન વિકાસ યોજનાઓનું સમગ્ર રાષ્ટ્રીય વિકાસ યોજનાઓ સાથે સંકલન.")})
add("sa2", ("भूमि निम्नीकरण की समस्या के समाधान के तीन तरीक़े सुझाइए।", "ભૂમિ અવક્રમણની સમસ્યાના ઉકેલની ત્રણ રીતો સૂચવો."),
    {0: ("वनारोपण, चरागाहों का उचित प्रबंधन और पशुचारण पर नियंत्रण।", "વનીકરણ, ગોચરનું યોગ્ય વ્યવસ્થાપન અને ચરાઈ પર નિયંત્રણ."), 1: ("रक्षक मेखला लगाना और काँटेदार झाड़ियाँ उगाकर रेत के टीलों को स्थिर करना।", "રક્ષક વૃક્ષ પટ્ટી વાવવી અને કાંટાળાં ઝાડવાં ઉગાડીને રેતીના ઢૂવા સ્થિર કરવા."),
     2: ("बंजर भूमि का उचित प्रबंधन, खनन पर नियंत्रण, और औद्योगिक जल का उचित परिष्करण और निपटान।", "પડતર જમીનનું યોગ્ય વ્યવસ્થાપન, ખાણકામ પર નિયંત્રણ, અને ઔદ્યોગિક પાણીનું યોગ્ય શુદ્ધીકરણ અને નિકાલ.")})
add("sa3", ("लेटराइट मृदा की तीन विशेषताएँ बताइए।", "લેટેરાઇટ જમીનનાં ત્રણ લક્ષણો જણાવો."),
    {0: ("यह उच्च तापमान और भारी वर्षा में तीव्र निक्षालन के परिणामस्वरूप विकसित होती है।", "તે ઊંચા તાપમાન અને ભારે વરસાદમાં તીવ્ર નિક્ષાલનના પરિણામે વિકસે છે."), 1: ("इसमें ह्यूमस कम है क्योंकि उच्च तापमान जीवाणु जैसे अपघटकों को नष्ट कर देता है।", "તેમાં સેન્દ્રિય દ્રવ્ય ઓછું છે કારણ કે ઊંચું તાપમાન બૅક્ટેરિયા જેવા વિઘટકોનો નાશ કરે છે."),
     2: ("खाद और संरक्षण विधियों से यह चाय और कॉफ़ी के लिए उपयोगी है; तमिलनाडु, आंध्र प्रदेश और केरल की लाल लेटराइट काजू के लिए उपयुक्त है।", "ખાતર અને સંરક્ષણ પદ્ધતિઓથી તે ચા અને કૉફી માટે ઉપયોગી છે; તમિળનાડુ, આંધ્ર પ્રદેશ અને કેરલની લાલ લેટેરાઇટ કાજુ માટે યોગ્ય છે.")})
add("la1", ("भारत में काली मृदा और जलोढ़ मृदा की विशेषताओं और वितरण का वर्णन कीजिए।", "ભારતમાં કાળી જમીન અને કાંપની જમીનનાં લક્ષણો અને વિતરણનું વર્ણન કરો."),
    {0: ("जलोढ़ मृदा उत्तरी मैदानों में है, जिसे सिंधु, गंगा और ब्रह्मपुत्र ने जमा किया; यह राजस्थान और गुजरात और पूर्वी तट के डेल्टाओं तक फैली है।", "કાંપની જમીન ઉત્તરનાં મેદાનોમાં છે, જે સિંધુ, ગંગા અને બ્રહ્મપુત્રએ જમા કરી; તે રાજસ્થાન અને ગુજરાત અને પૂર્વ કિનારાના મુખત્રિકોણો સુધી ફેલાયેલી છે."),
     1: ("जलोढ़ मृदा में रेत, सिल्ट और मृत्तिका है, यह पोटाश, फ़ॉस्फ़ोरस और चूने से भरपूर है, और बांगर (पुरानी) और खादर (नई, अधिक उपजाऊ) में बँटी है; यह गन्ने, चावल, गेहूँ और दलहन के लिए उपयुक्त है।", "કાંપની જમીનમાં રેતી, કાંપ અને માટી છે, તે પોટાશ, ફૉસ્ફરિક ઍસિડ અને ચૂનાથી સમૃદ્ધ છે, અને બાંગર (જૂની) અને ખાદર (નવી, વધુ ફળદ્રુપ)માં વહેંચાય છે; તે શેરડી, ડાંગર, ઘઉં અને કઠોળ માટે ઉત્તમ છે."),
     2: ("काली (रेगर) मृदा दक्कन ट्रैप के बेसाल्ट लावा से बनी है और महाराष्ट्र, सौराष्ट्र, मालवा, मध्य प्रदेश, छत्तीसगढ़ और गोदावरी और कृष्णा घाटियों में फैली है।", "કાળી (રેગુર) જમીન દખ્ખણ ટ્રૅપના બેસાલ્ટ લાવાથી બની છે અને મહારાષ્ટ્ર, સૌરાષ્ટ્ર, માળવા, મધ્ય પ્રદેશ, છત્તીસગઢ અને ગોદાવરી અને કૃષ્ણા ખીણોમાં ફેલાયેલી છે."),
     3: ("काली मृदा मृत्तिकामय है और नमी धारण करती है; यह कैल्शियम कार्बोनेट, मैग्नीशियम, पोटाश और चूने से भरपूर पर फ़ॉस्फ़ोरस में कम है; यह कपास के लिए उपयुक्त है।", "કાળી જમીન ચીકણી માટીવાળી છે અને ભેજ સંગ્રહે છે; તે કૅલ્શિયમ કાર્બોનેટ, મૅગ્નેશિયમ, પોટાશ અને ચૂનાથી સમૃદ્ધ પણ ફૉસ્ફરસમાં ઓછી છે; તે કપાસ માટે ઉત્તમ છે."),
     4: ("गर्म मौसम में काली मृदा में गहरी दरारें पड़ती हैं जिनसे वायु मिश्रण होता है, और गीली होने पर यह चिपचिपी हो जाती है, इसलिए इसकी जुताई पहली बारिश के बाद या मानसून-पूर्व काल में करनी पड़ती है।", "ગરમ હવામાનમાં કાળી જમીનમાં ઊંડી તિરાડો પડે છે જેથી હવાની અવરજવર થાય છે, અને ભીની થતાં તે ચીકણી બને છે, તેથી તેની ખેડ પહેલા વરસાદ પછી કે ચોમાસા પહેલાં કરવી પડે છે.")})
add("la2", ("मृदा अपरदन क्या है? इसके कारण और मृदा संरक्षण के चार तरीक़े समझाइए।", "જમીન ધોવાણ શું છે? તેનાં કારણો અને જમીન સંરક્ષણની ચાર પદ્ધતિઓ સમજાવો."),
    {0: ("मृदा के आवरण का कटाव और उसका बह जाना मृदा अपरदन है; मानवीय क्रियाएँ मृदा निर्माण और अपरदन के संतुलन को भंग करती हैं।", "જમીનના આવરણનો ઘસારો અને તેનું વહી જવું જમીન ધોવાણ છે; માનવ પ્રવૃત્તિઓ જમીન નિર્માણ અને ધોવાણનું સંતુલન તોડે છે."),
     1: ("कारण: वनोन्मूलन, अति पशुचारण, निर्माण, खनन और ढाल पर ऊपर से नीचे जुताई जैसे ग़लत तरीक़े; प्राकृतिक कारक जल, पवन और हिमनदी हैं।", "કારણો: જંગલોનો નાશ, અતિચરાઈ, બાંધકામ, ખાણકામ અને ઢોળાવ પર ઉપરથી નીચે ખેડ જેવી ખોટી પદ્ધતિઓ; કુદરતી પરિબળો પાણી, પવન અને હિમનદી છે."),
     2: ("बहता जल अवनालिकाएँ और उत्खात भूमि बनाता है (चंबल बेसिन में खड्ड); जल चादर अपरदन भी करता है, और पवन ढीली मृदा उड़ा ले जाती है।", "વહેતું પાણી કોતરો અને ઉજ્જડ જમીન બનાવે છે (ચંબલના થાળામાં કોતરો); પાણી પડ ધોવાણ પણ કરે છે, અને પવન છૂટી માટી ઉડાડી જાય છે."),
     3: ("समोच्च जुताई और सीढ़ीदार कृषि (जैसे पश्चिमी और मध्य हिमालय में) ढलानों पर जल को धीमा करती हैं।", "સમોચ્ચ ખેડ અને પગથિયાં આકારની ખેતી (જેમ કે પશ્ચિમ અને મધ્ય હિમાલયમાં) ઢોળાવો પર પાણીને ધીમું કરે છે."),
     4: ("पट्टी कृषि और रक्षक मेखला पवन की शक्ति तोड़ती हैं; रक्षक मेखलाओं ने पश्चिमी भारत में रेत के टीलों को स्थिर किया है।", "પટ્ટીદાર ખેતી અને રક્ષક વૃક્ષ પટ્ટી પવનનું જોર તોડે છે; રક્ષક વૃક્ષ પટ્ટીઓએ પશ્ચિમ ભારતમાં રેતીના ઢૂવા સ્થિર કર્યા છે.")})
add("cb1", ("स्रोत पढ़िए और प्रश्नों के उत्तर दीजिए।\n\n*\"जून 1992 में 100 से भी अधिक राष्ट्राध्यक्ष ब्राज़ील के शहर रियो डी जेनेरो में प्रथम अंतर्राष्ट्रीय पृथ्वी सम्मेलन में एकत्रित हुए। सम्मेलन का आयोजन विश्व स्तर पर उभरते पर्यावरण संरक्षण और सामाजिक-आर्थिक विकास की समस्याओं का हल ढूँढ़ने के लिए किया गया था।\"* (NCERT)\n\n"
             "(i) पृथ्वी सम्मेलन क्यों आयोजित किया गया? (1)\n\n(ii) सम्मेलन में स्वीकृत एजेंडा का नाम बताइए। (1)\n\n(iii) इस एजेंडा का मुख्य उद्देश्य और स्थानीय निकायों से इसकी अपेक्षा समझाइए। (2)",
             "સ્રોત વાંચો અને પ્રશ્નોના જવાબ આપો.\n\n*\"જૂન 1992માં 100થી વધુ રાષ્ટ્રના વડાઓ બ્રાઝિલના રિયો ડી જાનેરોમાં પ્રથમ આંતરરાષ્ટ્રીય પૃથ્વી પરિષદ માટે એકઠા થયા. વૈશ્વિક સ્તરે પર્યાવરણ સંરક્ષણ અને સામાજિક-આર્થિક વિકાસની તાકીદની સમસ્યાઓ ઉકેલવા આ પરિષદ યોજાઈ હતી.\"* (NCERT)\n\n"
             "(i) પૃથ્વી પરિષદ શા માટે યોજાઈ? (1)\n\n(ii) પરિષદમાં સ્વીકારાયેલા કાર્યક્રમનું નામ આપો. (1)\n\n(iii) આ કાર્યક્રમનો મુખ્ય હેતુ અને સ્થાનિક સરકારો પાસેથી તેની અપેક્ષા સમજાવો. (2)"),
    {0: ("(i) विश्व स्तर पर पर्यावरण संरक्षण और सामाजिक-आर्थिक विकास की तात्कालिक समस्याओं का हल ढूँढ़ने के लिए।", "(i) વૈશ્વિક સ્તરે પર્યાવરણ સંરક્ષણ અને સામાજિક-આર્થિક વિકાસની તાકીદની સમસ્યાઓ ઉકેલવા."), 1: ("(ii) एजेंडा 21।", "(ii) એજન્ડા 21."),
     2: ("(iii) इसका लक्ष्य समान हितों, पारस्परिक आवश्यकताओं और सम्मिलित ज़िम्मेदारियों के अनुसार विश्व सहयोग से पर्यावरणीय क्षति, ग़रीबी और रोगों से निपटना है; हर स्थानीय निकाय को अपना स्थानीय एजेंडा 21 बनाना चाहिए।", "(iii) તેનું લક્ષ્ય સમાન હિતો, પરસ્પર જરૂરિયાતો અને સહિયારી જવાબદારીઓ મુજબ વૈશ્વિક સહકારથી પર્યાવરણીય નુકસાન, ગરીબી અને રોગો સામે લડવાનું છે; દરેક સ્થાનિક સરકારે પોતાનો સ્થાનિક એજન્ડા 21 બનાવવો જોઈએ.")})
add("cb2", ("स्रोत पढ़िए और प्रश्नों के उत्तर दीजिए।\n\n*\"काली मृदा बहुत महीन कणों अर्थात् मृत्तिका से बनी है। इसकी नमी धारण करने की क्षमता बहुत होती है। इसके अलावा, यह मृदा पोषक तत्त्वों, जैसे कैल्शियम कार्बोनेट, मैग्नीशियम, पोटाश और चूने से परिपूर्ण होती है। इस मृदा में फ़ॉस्फ़ोरस की मात्रा कम होती है। गर्म और शुष्क मौसम में इस मृदा में गहरी दरारें पड़ जाती हैं, जिससे इसमें अच्छी तरह वायु मिश्रण हो जाता है।\"* (NCERT)\n\n"
             "(i) काली मृदा किस फ़सल के लिए सबसे उपयुक्त है? (1)\n\n(ii) काली मृदा में किस पोषक तत्त्व की कमी है? (1)\n\n(iii) काली मृदा की जुताई पहली बारिश के तुरंत बाद या मानसून-पूर्व काल में क्यों करनी चाहिए? एक और विशेषता बताइए। (2)",
             "સ્રોત વાંચો અને પ્રશ્નોના જવાબ આપો.\n\n*\"કાળી જમીન ખૂબ ઝીણા કણો એટલે કે માટીથી બનેલી છે. તે ભેજ સંગ્રહવાની ક્ષમતા માટે જાણીતી છે. વળી, તે કૅલ્શિયમ કાર્બોનેટ, મૅગ્નેશિયમ, પોટાશ અને ચૂના જેવાં પોષક તત્ત્વોથી સમૃદ્ધ છે. આ જમીનમાં ફૉસ્ફરસનું પ્રમાણ સામાન્ય રીતે ઓછું હોય છે. ગરમ હવામાનમાં તેમાં ઊંડી તિરાડો પડે છે, જેથી જમીનમાં સારી રીતે હવાની અવરજવર થાય છે.\"* (NCERT)\n\n"
             "(i) કાળી જમીન કયા પાક માટે સૌથી યોગ્ય છે? (1)\n\n(ii) કાળી જમીનમાં કયા પોષક તત્ત્વની અછત છે? (1)\n\n(iii) કાળી જમીનની ખેડ પહેલા વરસાદ પછી તરત અથવા ચોમાસા પહેલાં કેમ કરવી જોઈએ? એક વધુ લક્ષણ જણાવો. (2)"),
    {0: ("(i) कपास।", "(i) કપાસ."), 1: ("(ii) फ़ॉस्फ़ोरस।", "(ii) ફૉસ્ફરસ."),
     2: ("(iii) गीली होने पर यह चिपचिपी हो जाती है और इस पर काम करना कठिन होता है, इसलिए हल्की नमी में इसकी जुताई की जाती है; गर्म मौसम में इसमें गहरी दरारें भी पड़ती हैं, जिनसे वायु मिश्रण होता है।", "(iii) ભીની થતાં તે ચીકણી બને છે અને તેના પર કામ કરવું અઘરું છે, તેથી હળવા ભેજમાં તેની ખેડ થાય છે; ગરમ હવામાનમાં તેમાં ઊંડી તિરાડો પણ પડે છે, જેથી હવાની અવરજવર થાય છે.")})
